PROMPTS = [
 dict(id="Q01", persona="Executive", q="Which categories earn our margin, and how is each trending?",
  why="Shows where the profit actually comes from, so promotion and space decisions follow margin, not just sales.",
  sql="SELECT category, round(sum(net_sales),0) AS net_sales, round(sum(margin),0) AS margin, round(sum(margin)/sum(net_sales),3) AS margin_rate FROM {S}.gold_daily_store_category GROUP BY category ORDER BY margin DESC"),
 dict(id="Q02", persona="Executive", q="Which promotions lost us money, even though they sold more?",
  why="Separates promotions that grew margin from those that only moved volume at a deep discount.",
  sql="SELECT promo_name, discount_pct, round(lift,2) AS volume_lift, round(margin_change_per_day,0) AS margin_change_per_day, verdict FROM {S}.gold_promo_effectiveness ORDER BY margin_change_per_day LIMIT 10"),
 dict(id="Q03", persona="Executive", q="Where are stock-outs costing us the most (estimated)?",
  why="Puts a money figure on empty shelves for the highest-velocity items, so replenishment gets prioritised. It is an estimate, not a measurement.",
  sql="SELECT category, count(*) AS store_sku_weeks_out, round(sum(est_lost_units),0) AS est_lost_units, round(sum(est_lost_margin),0) AS est_lost_margin FROM {S}.gold_stockout_exposure GROUP BY category ORDER BY est_lost_margin DESC"),
 dict(id="Q04", persona="Executive", q="How does sales compare by region?",
  why="Shows which regions carry the business and which lag, for regional planning.",
  sql="SELECT region, round(sum(net_sales),0) AS net_sales, round(sum(margin),0) AS margin, sum(transactions) AS transactions FROM {S}.gold_daily_store_category GROUP BY region ORDER BY net_sales DESC"),
 dict(id="Q05", persona="Business analytics", q="How many loyalty customers are still buying 1, 3, 6 and 12 months after their first purchase?",
  why="Retention is the cheapest growth lever; this shows how fast loyalty customers drift away.",
  sql="WITH c0 AS (SELECT cohort_month, active_customers AS n0 FROM {S}.gold_loyalty_cohorts WHERE months_since = 0) SELECT g.months_since, round(avg(g.active_customers / c0.n0),3) AS share_still_buying FROM {S}.gold_loyalty_cohorts g JOIN c0 ON g.cohort_month = c0.cohort_month WHERE g.months_since IN (0,1,3,6,12) GROUP BY g.months_since ORDER BY g.months_since"),
 dict(id="Q06", persona="Business analytics", q="Which products are bought together most often?",
  why="Drives bundles, shelf placement and recommendations; lift says how much more often than chance.",
  sql="SELECT sku_a, sku_b, together, round(lift,1) AS lift FROM {S}.gold_basket_affinity ORDER BY lift DESC LIMIT 10"),
 dict(id="Q07", persona="Business analytics", q="Where do returns and discounts eat into sales?",
  why="Finds the categories where margin leaks through returns and markdowns.",
  sql="SELECT category, round(sum(returns_value)/sum(gross_net_sales),3) AS return_rate_value, round(sum(discount_given)/(sum(gross_net_sales)+sum(discount_given)),3) AS discount_rate FROM {S}.gold_margin_leakage GROUP BY category ORDER BY return_rate_value DESC"),
 dict(id="Q08", persona="Business analytics", q="When during the day do we sell the most?",
  why="Staffing and replenishment timing follow the hourly shape of demand.",
  sql="SELECT hour(event_ts) AS hour_of_day, count(DISTINCT txn_id) AS transactions, round(sum(net_sales),0) AS net_sales FROM {S}.silver_sales_lines GROUP BY hour(event_ts) ORDER BY hour_of_day"),
 dict(id="Q09", persona="Data engineering", q="How fresh and complete is the data behind these numbers?",
  why="Shows that the numbers can be trusted: latency, late data, duplicates removed and rows set aside.",
  sql="SELECT bronze_rows, silver_rows, quarantined_rows, duplicates_removed_est, round(median_latency_min,1) AS median_latency_min, round(p95_latency_min,1) AS p95_latency_min, round(late_share,4) AS late_share, latest_event_ts FROM {S}.gold_data_trust"),
 dict(id="Q10", persona="Data engineering", q="Which rows were rejected and why?",
  why="Bad records are kept and explained, not silently dropped, so the data team can fix the source.",
  sql="SELECT reason, count(*) AS rows, count(DISTINCT store_id) AS stores_affected FROM {S}.silver_quarantine GROUP BY reason"),
]
